  { method: 'connectEvent', args: ['stage_blueprint', 'Input', 'onKeyDown_ArrowRight', 'DoMoveRight'] },
  { method: 'connectEvent', args: ['stage_blueprint', 'Input', 'onKeyDown_ArrowUp',    'DoMoveUp'] },
